package dev.veltraph.client.combat.ghost;

import dev.veltraph.client.combat.sven.SvenBindingProfile;
import dev.veltraph.client.gui.MenuSnapshot;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class GhostBuffControllerTest {
    final SvenBindingProfile.Buff b=new SvenBindingProfile.Buff("minecraft:compass","Private opener","SkyBlock","Cookie","Cookie Menu","Potion States","Potions ",List.of("Jump Boost"),"Desired state","Next Page","", ".*","start","end","inactive","row","marker","off");
    MenuSnapshot m(String title,String name,List<String> lore,int revision){return new MenuSnapshot(2,title,List.of(new MenuSnapshot.Slot(10,name,lore,false)),revision);}
    GhostBuffController ready(){var f=new GhostBuffController(b);assertEquals(GhostBuffController.Kind.SELECT_SLOT_EIGHT,f.tick(null,true,true).kind());f.slotEightObserved(true);assertEquals(GhostBuffController.Kind.USE_MENU_ITEM,f.tick(null,true,true).kind());f.tick(m("SkyBlock","Cookie",List.of(),1),false,true);assertEquals(GhostBuffController.Kind.CLICK,f.tick(m("SkyBlock","Cookie",List.of(),1),false,true).kind());f.tick(m("Cookie Menu","Potion States",List.of(),2),false,true);assertEquals(GhostBuffController.Kind.CLICK,f.tick(m("Cookie Menu","Potion States",List.of(),2),false,true).kind());f.tick(m("Potions 1","Jump Boost",List.of("Original"),3),false,true);return f;}
    void closeAndContinue(GhostBuffController f,boolean nativeEffect){assertEquals(GhostBuffController.Kind.CLOSE,f.tick(m("Potions 1","Jump Boost",List.of("Original"),100),false,nativeEffect).kind());assertEquals(GhostBuffController.Kind.COMPLETE,f.tick(null,true,nativeEffect).kind());assertEquals(nativeEffect,f.nativeJumpBoostAtClose());}
    @Test void ordinaryObservedDesiredLoreClosesAndContinues(){var f=ready();assertEquals(GhostBuffController.Kind.CLICK,f.tick(m("Potions 1","Jump Boost",List.of("Original"),3),false,true).kind());f.tick(m("Potions 1","Jump Boost",List.of("Desired state"),4),false,false);f.tick(m("Potions 1","Jump Boost",List.of("Desired state"),4),false,false);closeAndContinue(f,false);assertEquals(Set.of("Jump Boost"),f.desiredLoreObserved());assertTrue(f.unresolved().isEmpty());}
    @Test void fiveAttemptsRemoveUnappliedNameAndContinueWithoutForgedEffectReceipt(){var f=ready();for(int r=3;r<8;r++)assertEquals(GhostBuffController.Kind.CLICK,f.tick(m("Potions 1","Jump Boost",List.of("Original"),r),false,true).kind());assertEquals(GhostBuffController.Kind.NONE,f.tick(m("Potions 1","Jump Boost",List.of("Original"),8),false,true).kind());assertEquals(GhostBuffController.State.TOGGLE_POTIONS,f.state());f.tick(m("Potions 1","Jump Boost",List.of("Original"),8),false,true);closeAndContinue(f,true);assertTrue(f.desiredLoreObserved().isEmpty());assertTrue(f.unresolved().get("Jump Boost").startsWith("Five native toggle"));}
    @Test void sameRevisionPartialStateCannotSpendAdditionalAttempt(){var f=ready();assertEquals(GhostBuffController.Kind.CLICK,f.tick(m("Potions 1","Jump Boost",List.of("Original"),3),false,true).kind());for(int i=0;i<10;i++)assertEquals(GhostBuffController.Kind.NONE,f.tick(m("Potions 1","Jump Boost",List.of("Original"),3),false,true).kind());assertTrue(f.unresolved().isEmpty());assertTrue(f.desiredLoreObserved().isEmpty());}
    @Test void missingNextPageClosesWithUnresolvedStatusAndSameContinuation(){var f=ready();f.tick(m("Potions 1","Other",List.of(),3),false,true);f.tick(m("Potions 1","No next selector",List.of(),3),false,true);assertEquals(GhostBuffController.State.CLOSE_SBMENU,f.state());closeAndContinue(f,true);assertEquals("Source next-page selector absent",f.unresolved().get("Jump Boost"));assertTrue(f.desiredLoreObserved().isEmpty());}
    @Test void fiveAcknowledgedPageChangesCloseUnresolvedThenContinue(){var f=ready();for(int p=1;p<=5;p++){f.tick(m("Potions "+p,"Other",List.of(),10+p),false,true);assertEquals(GhostBuffController.Kind.CLICK,f.tick(m("Potions "+p,"Next Page",List.of(),10+p),false,true).kind());assertEquals(GhostBuffController.Kind.NONE,f.tick(m("Potions "+p,"Next Page",List.of(),10+p),false,true).kind());f.tick(m("Potions "+(p+1),"Other",List.of(),11+p),false,true);}f.tick(m("Potions 6","Other",List.of(),30),false,true);f.tick(m("Potions 6","Next Page",List.of(),30),false,true);assertEquals(GhostBuffController.State.CLOSE_SBMENU,f.state());closeAndContinue(f,true);assertEquals("Five source page requests exhausted",f.unresolved().get("Jump Boost"));}
    @Test void repeatedSamePageNeedsFreshRevisionForEachBoundedRequest(){var f=ready();f.tick(m("Potions 1","Other",List.of(),3),false,true);for(int r=3;r<8;r++)assertEquals(GhostBuffController.Kind.CLICK,f.tick(m("Potions 1","Next Page",List.of(),r),false,true).kind());f.tick(m("Potions 1","Next Page",List.of(),8),false,true);closeAndContinue(f,true);assertTrue(f.desiredLoreObserved().isEmpty());}
    @Test void readableSourceCloseMessageContinuesWithExplicitUnresolvedStatus(){var f=ready();f.sourceCloseMessage();assertEquals(GhostBuffController.State.CLOSE_SBMENU,f.state());closeAndContinue(f,true);assertEquals("Source configured close-message prefix observed",f.unresolved().get("Jump Boost"));assertTrue(f.desiredLoreObserved().isEmpty());}
    @Test void closeMessageMayCloseEarlierOwnedCookieMenuWithoutAnyPotionClaim(){var f=new GhostBuffController(b);f.slotEightObserved(true);f.sourceCloseMessage();assertEquals(GhostBuffController.Kind.CLOSE,f.tick(m("Cookie Menu","Potion States",List.of(),1),false,true).kind());assertEquals(GhostBuffController.Kind.COMPLETE,f.tick(null,true,true).kind());assertTrue(f.desiredLoreObserved().isEmpty());}
    @Test void foreignMenusAndAmbiguousSelectorsRemainTerminalFailures(){var f=ready();assertEquals(GhostBuffController.Kind.FAILED,f.tick(m("Foreign","Jump Boost",List.of("Desired state"),4),false,true).kind());f=ready();var duplicate=new MenuSnapshot(2,"Potions 1",List.of(new MenuSnapshot.Slot(1,"Jump Boost",List.of(),false),new MenuSnapshot.Slot(2,"Jump Boost",List.of(),false)),4);assertEquals(GhostBuffController.Kind.FAILED,f.tick(duplicate,false,true).kind());}
}
